\label{definition:isotropyTrace}
The integers $\nu_{ij} \in \{0, \ldots, p_i-1\}$, $j=1, \ldots, \mathrm{rk}(\mathcal{V})$ are called the {\em isotropies} of $\mathcal{V}$ at $P_i$. The integer
\begin{gather*}
\iota(\mathcal{V},P_i):= \sum_{i=1}^{\mathrm{rk}(\mathcal{V})} \nu_{ij} \in \mathbb{Z}_{\geq 0}
\end{gather*}
is called the {\em isotropy trace} of $\mathcal{V}$ at $P_i$.

\label{theorem:RRochOrbifold}
Let $\mathcal{V}$ be a vector bundle over an orbifold curve $X$. Then
\begin{gather*}
\chi(X,\mathcal{V}) = \mathrm{rk}(\mathcal{V})(1 - g_X) + \deg(\mathcal{V}) - \left( \sum_{i=1}^n \frac{\iota(\mathcal{V},P_i)}{p_i} \right).
\end{gather*}

\label{theorem:Chevalley--Weil}
Let $\rho_i$ be an irreducible representation of~$G$. For each ramification point $Q_j \in Y$ choose some $R_j\stackrel{f}\mapsto Q_j$. Then the multiplicity $d_i = d(\rho_i)$ of $\rho_i$ in $\rho_f$ is given by
\begin{gather*}
d_i = \epsilon + \dim \rho_i\left(g_Y-1 + n - \sum_{j=1}^n \frac{1}{p_j} \right) + \sum_{j=1}^r \sum_{k=1}^{e_j-1} N_k(\rho_i;\gamma_{R_j})\left(1 - \frac{k}{e_j}\right) \\
\hphantom{d_i =}{} - \sum_{j=1}^n \sum_{k=1}^{p_j-1} N_k\Big(e^{\frac{-2\pi i}{p_j}}\rho_i;\gamma_{P_j}\Big)\frac{k}{p_j},
\end{gather*}
where $\epsilon = 1$ if $\rho_i = 1$ and $\epsilon = 0$ otherwise.

\label{prop:GActionOnH1Trivial} The action of $G$ on $H^1\big(X, \Omega^1_X\big)$ is trivial. Therefore
\begin{gather*}
\dim H^1\big(X, \Omega^1_X\big)^{\rho_i} = \epsilon = \begin{cases} 1& \text{if } \rho_i = 1, \\
0& \text{if } \rho_i \neq 1,
 \end{cases}
\end{gather*}
for any irreducible representation $\rho_i$ of $G$.

\label{prop:ramificationPiece} Let $\rho_i$ be an irreducible representation of $G$. For each ramification point $Q_j \in Y$ choose some $R_j\stackrel{f}\rightarrow Q_j$. Then
\begin{gather*}
\chi\big(Y, \big(f_*\Omega_{X/Y}^1\big)^{\rho_i} \big) = \dim \rho_i \sum_{j=1}^r \mathrm{rk} ( \rho_i(\gamma_{R_j}) - I ).
\end{gather*}

\label{prop:rankV}
\begin{gather*}
\mathrm{rk} \mathcal{V} = (\dim \rho_i)^2.
\end{gather*}

\label{prop:parabolicPiece}
\begin{gather*}
\deg \big(f_*\mathcal{O}_{X}^{\rho_i}\big) = -\dim \rho_i \sum_{j=1}^r \sum_{k=1}^{e_j-1} N_k(\rho_i;\gamma_{R_j})\frac{k}{e_j}.
\end{gather*}

\label{prop:isotropyV}
\begin{gather*}
\left( \sum_{i=1}^n \frac{\iota(\mathcal{V},P_i)}{p_i} \right)=\sum_{j=1}^n \sum_{k=1}^{p_j-1} N_k\big(e^{\frac{-2\pi i}{p_j}}\rho_i;\gamma_{P_j}\big)\frac{k}{p_j}.
\end{gather*}

\label{theorem:Chevalley--WeilModForms}
Let $\Gamma\triangleleft \mathrm{PSL}_2(\mathbb{Z})$ be a finite-index normal subgroup, and let $G:=\mathrm{PSL}_2(\mathbb{Z})/\Gamma$. Let $\rho\neq 1$ be an irreducible representation of $G$. Then the multiplicity of $\rho$ in $\rho_{\Gamma}$ is given by
\begin{gather*}
d = -\frac{5}{12}\dim \rho + \sum_{k=1}^{e-1} N_k(\rho;T)\left(1 - \frac{k}{e}\right) - \frac{\operatorname{Tr}(\rho(S))}{4} + \frac{\zeta^2_3\operatorname{Tr}\big(\rho\big(R^{-1}\big)\big)}{3(1-\zeta_3^{2})} + \frac{\zeta_3\operatorname{Tr}(\rho(R))}{3(1-\zeta_3)},\end{gather*}
where $\zeta_3:= e^{2\pi i/3}$.

sing the notation of Theorem~\ref{theorem:Chevalley--Weil}, note first that $\epsilon = 0$ always since we are assuming $\rho \neq 1$. We also have that $g_{X(1)}=0$, $n=2$, $p_1 = 2$, $p_2 = 3$, which gives a contribution of $\dim \rho/6$ in Theorem~\ref{theorem:Chevalley--WeilModForms}. As stated above, there is only one ramification point $\infty \in X(1)$ of index $e$ and with local monodromy given by the image of $T$ in $G$, which gives the second term. As for the remaining terms, since the order of $\rho(S)$ and $\rho(R^{-1})$ is low it is more convenient computationally to express the eigenvalue multiplicities in terms of traces. In particular, note that
\begin{gather*}
\operatorname{Tr}(\rho(S)) = N_0(\rho(S)) - N_1(\rho(S)) = N_1(-\rho(S)) - N_0(-\rho(S)) = 2N_1(-\rho(S)) - \dim \rho
\end{gather*}
and similarly
\begin{gather*}
\frac{N_1\big(e^{-2\pi i /3}\rho;R^{-1}\big)}{3} + 2\cdot\frac{N_2\big(e^{-2\pi i /3}\rho;R^{-1}\big)}{3} = \frac{\dim \rho}{3}-\frac{\zeta^2_3\operatorname{Tr}\big(\rho\big(R^{-1}\big)\big)}{3\big(1-\zeta_3^{2}\big)} - \frac{\zeta_3\operatorname{Tr}(\rho(R))}{3(1-\zeta_3)},
\end{gather*}
yielding the simplified formula.

\label{prop:TRamification}For each one of the irreducible representations appearing in Table~{\rm \ref{table:p14}}, we have
\begin{gather*}
N_k(\lambda; T) = 1, \qquad N_k(\mu_s; T) = 1, \qquad N_k(\theta_t; T) = 1, \\
 N_k(\chi_1; T) = \begin{cases} 1 &\text{if } \left(\dfrac{k}{p}\right)_L =1, \vspace{1mm}\\
 0 &\text{if } \left(\dfrac{k}{p}\right)_L = -1,
\end{cases} \qquad N_k(\chi_2; T) = \begin{cases} 0 &\text{if } \left(\dfrac{k}{p}\right)_L =1, \vspace{1mm}\\
 1 &\text{if } \left(\dfrac{k}{p}\right)_L = -1,
\end{cases}
\end{gather*}
where $k=1,\ldots,p-1$.

or any representation $\rho$ of $G$, let $P(\rho;T)$ be the characteristic polynomial of $\rho(T)$. Since $\rho(T)^p = I_{\dim \rho}$, we know that the roots of $P(\rho;T)$ are necessarily $p$-th roots of unity. The polynomial itself can be computed from Table \ref{table:p14} by first computing the traces of $\rho(T^k)$, $k=0,\ldots, p-1$ and then compute from these traces the coefficients of $P(\rho;T)$ using Newton's identities. Now the subgroup $\big\{T^k\big\}$ breaks up into two conjugacy classes:
\begin{gather*}
\big\{T^k\big\} \cap [T] = \big\{ 
\left( \begin{smallmatrix}
 1 & r\\
 0 & 1
\end{smallmatrix}\right)\colon r \text{ is a square in } \mathbb{F}_p\big\}, \\
\big\{T^k\big\} \cap \big[
\left( \begin{smallmatrix}
 1 & 0\\
 u_p & 1
\end{smallmatrix}\right)\big] = \big\{ 
\left( \begin{smallmatrix}
 1 & n\\
 0 & 1
\end{smallmatrix}\right)\colon n \text{ is not a square in } \mathbb{F}_p\big\},
\end{gather*}
therefore the coefficients of $P(\rho;T)$ are polynomials in the last two columns of Table \ref{table:p14}. For $\rho = \lambda, \mu_s$ and $\theta_t$, it follows that $P(\rho;T)$ has coefficients in $\mathbb{Q}$, and therefore
\begin{gather*}
\gcd\big(P(\rho;T), x^p-1\big) = \begin{cases} x-1 \\
 \Phi_p \\
 x^p-1 \end{cases} \in \mathbb{Q}[x],
\end{gather*}
where $\Phi_p$ is the $p$-th cyclotomic polynomial, which is irreducible over $\mathbb{Q}$. Suppose first $\rho=\lambda$. If $\gcd(P(\lambda;T),x^p-1) = (x-1)$ then necessarily $\lambda(T)= I_p$, which is impossible since Table \ref{table:p14} gives $\operatorname{Tr}\lambda(T) = 0 \neq p$. If $\gcd(P(\lambda;T),x^p-1) = \Phi_p$, then $P(\lambda;T)$ factors over $\mathbb{Q}$ as $\Phi_p \cdot(x - \zeta_p)$, for some $p$-th root of unity $\zeta_p$. But since $p\geq 5$, the only such polynomial $(x - \zeta_p)$ defined over~$\mathbb{Q}$ is~$(x-1)$, therefore $P(\lambda;T) = x^p-1$ necessarily, which gives the formula
\begin{gather*}
N_k(\lambda; T) = 1, \qquad k=1, \ldots, p-1.
\end{gather*}
For $\rho=\mu_s$, again we cannot have $\gcd(P(\mu_s;T),x^p-1) = (x-1)$ since none of the $\mu_s(T)$ is the identity, the trace being $1\neq 0$. If $\gcd(P(\mu_s;T),x^p-1) = \Phi_p$ then $P(\mu_s;T)$ factors as $\Phi_p\cdot q(x)$, for some quadratic polynomial $q(x)$. The only $\mathbb{Q}$-rational quadratic polynomials having only $p$-th roots as their solutions are $(x-1)^2$ and $\Phi_3$. Since $p\geq 5$, the latter cannot occur and $P(\mu_s;T) = \Phi_p\cdot(x-1)^2$. A similar reasoning shows that $P(\theta_t;T) = \Phi_p$, so the first row of Proposition~\ref{prop:TRamification} is proved. It remains to compute $P(\rho;T)$ for $\rho=\chi_1,\chi_2$. Note that for these two representations the last two columns of Table~\ref{table:p14} have coefficients in $\mathbb{Q}(\sqrt{p})$ and therefore $P(\rho;T)$ is $\mathbb{Q}(\sqrt{p})$-rational. Now the $p$-th cyclotomic polynomial factors over $\mathbb{Q}(\sqrt{p})$ as
\begin{gather*}\Phi_p = \Phi^{(r)}_p\cdot \Phi^{(n)}_p, \qquad \in \mathbb{Q}(\sqrt{p})[x],\end{gather*}
where $\Phi^{(r)}_p$ (resp.~$\Phi^{(n)}_p$) is the irreducible monic polynomial of degree $(p-1)/2$ over $\mathbb{Q}(\sqrt{p})$ whose roots are the $p$-th roots of unity of the form $e^{2\pi i r/p}$ (resp. $e^{2\pi i n/p}$), with $r$ (resp. $n$) a quadratic residue mod $p$ (resp. quadratic non-residue mod $p$). Let now $\rho=\chi_1$. Then $\gcd(P(\chi_1;T), x^p-1)$ is a non-constant $\mathbb{Q}(\sqrt{p})$-rational polynomial and it cannot be $(x-1)$ for otherwise $\chi(T)$ would be the identity, which is impossible since $\operatorname{Tr}(\chi_1(T)) \neq p$. Since $\deg P(\chi_1;T) = (p+1)/2$, the only other possibilities are that $\gcd(P(\chi_1;T), x^p-1) = \Phi^{(r)}_p$ or $\Phi^{(n)}_p $, so that $P(\chi_1;T) = (x-1)\Phi^{(r)}_p$ or $(x-1)\Phi^{(n)}_p$. To determine which one it is, note that the sum of the roots of $(x-1)\Phi^{(r)}_p$ can be computed by a Gauss sum and it is equal to $1/2(-1-\sqrt{p})$. This must coincide with the negative of $\operatorname{Tr}(\chi_1(T))$, so by Table~\ref{table:p14} we see that this is indeed the correct factorization. Similarly we may deduce that $P(\chi_2;T) = (x-1)\Phi^{(n)}_p$, which concludes the proof.

